import { test, expect } from '@playwright/test';

test.describe('Mobile Responsive Modal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal');
  });

  test('should display modal responsively on mobile devices', async ({ page }) => {
    // Setup: Open modal using getByRole
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify modal content is visible
    const modalContent = page.getByRole('main');
    await expect(modalContent).toBeVisible();

    // Verify modal title is visible
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).toBeVisible();

    // Verify close button is visible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify modal is responsive on mobile
    await page.setViewportSize({ width: 375, height: 667 });
    await expect(modal).toHaveStyle('max-width: 100%');
    await expect(modalContent).toHaveStyle('max-width: 100%');

    // Verify modal content is readable on mobile
    await expect(modalContent).toHaveTextContent('Modal content');

    // Verify close button is accessible
    await expect(closeButton).toBeEnabled();

    // Verify modal is closed when close button is clicked
    await closeButton.click();
    await expect(modal).not.toBeVisible();
  });

  test('should handle modal overflow on large mobile screens', async ({ page }) => {
    // Setup: Open modal using getByRole
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify modal content is visible
    const modalContent = page.getByRole('main');
    await expect(modalContent).toBeVisible();

    // Verify modal title is visible
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).toBeVisible();

    // Verify close button is visible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify modal is responsive on large mobile
    await page.setViewportSize({ width: 600, height: 1000 });
    await expect(modal).toHaveStyle('max-width: 100%');
    await expect(modalContent).toHaveStyle('max-width: 100%');

    // Verify modal content does not overflow
    await expect(modalContent).not.toHaveClass(/overflow/);

    // Verify modal content is still readable
    await expect(modalContent).toHaveTextContent('Modal content');

    // Verify close button is still accessible
    await expect(closeButton).toBeEnabled();

    // Verify modal is closed when close button is clicked
    await closeButton.click();
    await expect(modal).not.toBeVisible();
  });
});
